import{_ as t,c as a,o,ai as s}from"./chunks/framework.B63Sb1io.js";const r="/img/png/English/01.webp",g=JSON.parse('{"title":"外刊精读","titleTemplate":"外刊精读","description":"外刊精读","frontmatter":{"title":"外刊精读","titleTemplate":"外刊精读","description":"外刊精读","layout":"doc","navbar":true,"sidebar":true,"aside":false,"lastUpdated":true,"prev":false,"next":false},"headers":[],"relativePath":"post/kaoyan/English/waikan/20250901.md","filePath":"post/kaoyan/English/waikan/20250901.md","lastUpdated":1756788119000}'),n={name:"post/kaoyan/English/waikan/20250901.md"};function i(l,e,h,d,u,p){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="taylor-swift-and-travis-kelce-are-engaged" tabindex="-1">Taylor Swift and Travis Kelce are engaged. <a class="header-anchor" href="#taylor-swift-and-travis-kelce-are-engaged" aria-label="Permalink to &quot;Taylor Swift and Travis Kelce are engaged.&quot;">​</a></h1><blockquote><p>2025.9.1外刊精读，节选自 <a href="https://www.usatoday.com/story/entertainment/music/2025/08/26/taylor-swift-travis-kelce-engaged-how-he-asked-ring-details/73961753007/" target="_blank" rel="noreferrer">USA TODAY 2025.8.26</a></p></blockquote><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+r+'" alt="外刊精读" width="700px" style="border-radius:10px;"></div><br><br><p>It&#39;s a love story, and Taylor Swift said yes. The music superstar and three-time Super Bowl winner Travis Kelce announced that they&#39;re <span class="red">engaged</span> to be married, <span class="red">delighting</span> fans around the world. They shared a <span class="red">joint</span> post on Instagram on Tuesday afternoon, joking that &quot;Your English teacher and your gym teacher are getting married.&quot;</p><blockquote><p>这是一个爱情故事，泰勒·斯威夫特说了&quot;我愿意&quot;。美国流行音乐天后和三次超级碗冠军特拉维斯·凯尔斯宣布两人已订婚，这一消息让全球粉丝欣喜若狂。6 日下午，两人在 Instagram 上发布了联名帖子，并开玩笑说：&quot;你们的英语老师和体育老师要结婚了。&quot;</p></blockquote><ul><li><strong>engaged</strong> 已订婚的</li><li><strong>delighting</strong> 使愉快、高兴</li><li><strong>joint</strong> 联合的</li></ul><br><p>The <span class="red">mega</span>-famous couple shared a five-photo <span class="red">carousel</span> of Swift and Kelce, both 35, surrounded by flowers with Travis on one knee. While there&#39;s no word on when the <span class="red">nuptials</span> will take place, well wishes started <span class="red">pouring in</span> from the worlds of music and sports.</p><blockquote><p>这对超级巨星情侣在动态中分享了五张照片，组图中 35 岁的斯威夫特和凯尔西被鲜花环绕，男方单膝跪地。虽然尚未公布婚礼的具体日期，但来自音乐界和体育界的祝福已经开始涌现。</p></blockquote><ul><li><strong>mega</strong> 超级的（表示程度的前缀）</li><li><strong>carousel</strong> 旋转木马（此处译为“轮播图”）</li><li><strong>nuptials</strong> 婚礼</li><li><strong>pouring in</strong> 蜂拥而来，大量涌入</li></ul><h3 id="how-long-have-taylor-swift-and-travis-kelce-been-together-what-to-know-about-their-timeline" tabindex="-1">How long have Taylor Swift and Travis Kelce been together? What to know about their timeline <a class="header-anchor" href="#how-long-have-taylor-swift-and-travis-kelce-been-together-what-to-know-about-their-timeline" aria-label="Permalink to &quot;How long have Taylor Swift and Travis Kelce been together? What to know about their timeline&quot;">​</a></h3><br><p>&quot;I was disappointed that she doesn&#39;t talk before or after her shows because she has to save her voice for the 44 songs that she sings,&quot; Kelce said to his brother, Jason, on their podcast at the time. Swift <span class="red">reached out</span> to him after he <span class="red">put her on blast</span> on &quot;New Heights,&quot; and the two began dating quietly until they went public when Swift attended the Chiefs vs. Bears game on Sept. 24, 2023.</p><blockquote><p>凯尔西在当时他们的播客节目中对他哥哥杰森说：&quot;她为了唱好 44 首歌而不得不保护嗓子，所以演出前后都不说话，这让我很失望。&quot;在凯尔西通过 &quot;New Heights&quot; 节目公开吐槽后，斯威夫特主动联系了他，两人开始低调交往，直到 2023 年 9 月 24 日斯威夫特现身酋长队对阵熊队的比赛，恋情才正式公开。</p></blockquote><ul><li><strong>reached out</strong> 主动联系</li><li><strong>put her on blast</strong> 向她公开喊话</li></ul><h3 id="donald-trump-to-taylor-swift-and-travis-kelce-i-wish-them-a-lot-of-luck" tabindex="-1">Donald Trump to Taylor Swift and Travis Kelce: &#39;I wish them a lot of luck&#39; <a class="header-anchor" href="#donald-trump-to-taylor-swift-and-travis-kelce-i-wish-them-a-lot-of-luck" aria-label="Permalink to &quot;Donald Trump to Taylor Swift and Travis Kelce: &#39;I wish them a lot of luck&#39;&quot;">​</a></h3><br><p>President Donald Trump hasn&#39;t always been Taylor Swift&#39;s biggest fan, but he had warm wishes for the musician and her football player fiancee Travis Kelce on their engagement. &quot;I think he&#39;s a great player. I think he&#39;s a great guy,&quot; Trump said at the White House on Tuesday. &quot;And I think that she&#39;s a <span class="red">terrific</span> person, so I wish them a lot of luck.&quot; Trump has repeatedly <span class="red">slammed</span> Swift, who <span class="red">endorsed</span> his 2024 Democratic <span class="red">opponent</span> Kamala Harris.</p><blockquote><p>唐纳德·特朗普总统并非泰勒·斯威夫特的歌迷，但这位音乐人与其橄榄球明星未婚夫特拉维斯·凯尔西订婚时，他送上了暖心祝福。特朗普周二在白宫表示：&quot;我认为他是名出色的球员，也是个很棒的小伙子。她也是个非常优秀的人，所以我祝他们好运。&quot;斯威夫特曾公开支持特朗普 2024 年大选的民主党竞争对手卡玛拉·哈里斯，特朗普此前多次对她大加抨击。</p></blockquote><ul><li><strong>terrific</strong> 极好的</li><li><strong>slam</strong> 抨击</li><li><strong>endorse</strong> 支持</li><li><strong>opponent</strong> 竞争对手</li></ul>',23)]))}const w=t(n,[["render",i]]);export{g as __pageData,w as default};
